<?php
require '../includes/functions.php'; verify_csrf(); $error='';
if ($_SERVER['REQUEST_METHOD']==='POST') { $q=db()->prepare('SELECT u.id,u.full_name,u.email,u.password_hash,u.department_id,r.name role FROM users u JOIN roles r ON r.id=u.role_id WHERE u.email=? AND u.is_active=1'); $q->execute([strtolower(trim($_POST['email']??''))]); $user=$q->fetch(); if ($user && password_verify($_POST['password']??'',$user['password_hash'])) { session_regenerate_id(true); unset($user['password_hash']); $_SESSION['user']=$user; redirect(match($user['role']) {'citizen'=>'citizen/dashboard.php','department_admin'=>'department/dashboard.php',default=>'admin/dashboard.php'}); } $error='Email or password is incorrect.'; }
$pageTitle='Sign in'; require '../includes/header.php'; ?><section class="panel form-narrow"><h1>Sign in</h1><?php if($error): ?><p class="error"><?= e($error) ?></p><?php endif; ?><form method="post"><?= csrf_field() ?><label for="email">Email</label><input id="email" type="email" name="email" required autocomplete="username"><label for="password">Password</label><input id="password" type="password" name="password" required autocomplete="current-password"><button>Sign in</button></form></section><?php require '../includes/footer.php'; ?>
